UPDATE INT_SERVERFUNCTION SET NAME = COALESCE(NULL, NAME), DESCRIPTION = COALESCE('Grava um evento na trilha de auditoria do workflow (usado pelo app para confirmar/desfazer modelo). Params: cicloId, tipo, crId, driverId, gestorId (0 = NULL), evento, statusDe, statusPara, comentario, autor, origem, agora', DESCRIPTION), TYPE = COALESCE(NULL, TYPE), JDBC_ID = NULL, CODE = COALESCE('INSERT INTO WORKFLOW_AUDITORIA (CICLO_ID, TIPO, CR_ID, DRIVER_ID, GESTOR_ID, EVENTO, STATUS_DE, STATUS_PARA, COMENTARIO, AUTOR, ORIGEM, CRIADO_EM)
VALUES ({{cicloId}}, ''{{tipo}}'', NULLIF({{crId}}, 0), NULLIF({{driverId}}, 0), NULLIF({{gestorId}}, 0), ''{{evento}}'', ''{{statusDe}}'', ''{{statusPara}}'', ''{{comentario}}'', ''{{autor}}'', ''{{origem}}'', ''{{agora}}'')', CODE), PUBLIC_EXECUTION = COALESCE(NULL, PUBLIC_EXECUTION), CRON_EXPRESSION = NULL, CRON_INPUT_JSON = NULL WHERE NAME = 'registrarEventoWorkflow';
